import * as THREE from './vendor/three.module.js';
import {GLTFLoader} from './vendor/GLTFLoader.js';
import {DRACOLoader} from './vendor/DRACOLoader.js';
import {artifacts} from './data.js';
import {createHeritageModel} from './artifact-models.js';
import {createDescentMarker,enhanceModel} from './model-presentation.js';
import {surfaceHeight,surfaceSites,modelSpan,advanceWalker} from './surface-logic.js';

export function createSurface(root,{world,icon,esc,onArtifact,onExit}){
 let dead=false,paused=false,frame,lastTime=0,drag=null,moved=false,yaw=0,pitch=0,state={x:0,z:2,yaw:0,pitch:0},elapsed=0,nearest=null;
 const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches,sites=surfaceSites(artifacts,world),keys=new Set(),touch=new Set(),cache=new Map(),resources=new Set();
 root.innerHTML=`<section class="surface-expedition" aria-label="First-person expedition on ${world}"><div class="surface-canvas"></div><header class="surface-hud"><div><span class="surface-world">${esc(world)} / FIRST PERSON</span><p>Walk among the echoes.</p></div><div class="surface-actions"><button data-surface-action="help" aria-expanded="false" aria-label="Walking controls">${icon('menu',18)}</button><button data-surface-action="mouse" aria-label="Lock mouse to look around" title="Lock mouse to look around">${icon('scan',18)}</button><button data-surface-action="exit" aria-label="Return to the globe">${icon('close',21)}</button></div></header><div class="surface-map"><label for="surface-destination">Go near an artifact</label><select id="surface-destination"><option value="">Choose a destination…</option>${sites.map(s=>`<option value="${s.artifact.id}">${esc(s.artifact.name)}${s.artifact.locationUncertain?' · location uncertain':''}</option>`).join('')}</select></div><div class="surface-help" hidden><b>Your expedition controls</b><p>W A S D to walk · drag to look · arrow keys to look · Shift to move faster · E to explore a nearby artifact.</p><p>On touchscreens, hold a direction button and drag the view. The destination menu takes you near an artifact.</p><p>Lock mouse is optional. Esc releases the mouse or returns to the globe.</p><button data-surface-action="help">Got it</button></div><div class="surface-crosshair" aria-hidden="true"></div><div class="surface-nearby"><span class="surface-distance"></span><button data-surface-action="explore" disabled>Walk toward an artifact</button></div><div class="surface-touch" aria-label="Walk controls"><button data-surface-move="forward" aria-label="Walk forward">↑</button><button data-surface-move="left" aria-label="Walk left">←</button><button data-surface-move="back" aria-label="Walk backward">↓</button><button data-surface-move="right" aria-label="Walk right">→</button></div><footer class="surface-note">Illustrative expedition · Artifacts brought together for learning. Terrain, spacing and model sizes are approximate; not a real walking route.</footer><span class="surface-status sr-only" role="status"></span></section>`;
 const $=s=>root.querySelector(s),stage=$('.surface-canvas');
 const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;stage.append(renderer.domElement);const canvas=renderer.domElement;canvas.tabIndex=0;canvas.setAttribute('aria-label',`First-person ${world} terrain. W A S D to walk, arrow keys or drag to look, E to explore.`);
 const scene=new THREE.Scene();scene.background=new THREE.Color(world==='Moon'?0x030712:0xa8755c);scene.fog=new THREE.FogExp2(world==='Moon'?0x141923:0xb57e60,world==='Moon'?.0035:.006);
 const camera=new THREE.PerspectiveCamera(68,1,.08,450);camera.rotation.order='YXZ';
 scene.add(new THREE.HemisphereLight(world==='Moon'?0xa6bedb:0xffdec5,world==='Moon'?0x2c2b31:0x7e4932,1.6));const sun=new THREE.DirectionalLight(0xffe7ce,3.0);sun.position.set(-55,75,-35);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-110,right:110,top:110,bottom:-110,far:240});sun.shadow.normalBias=.035;scene.add(sun);
 let seed=world==='Moon'?29:47;const random=()=>((seed=(seed*1664525+1013904223)>>>0)/4294967296);
 const terrain=new THREE.PlaneGeometry(240,240,110,110);terrain.rotateX(-Math.PI/2);const vertices=terrain.attributes.position,colors=[];for(let i=0;i<vertices.count;i++){const x=vertices.getX(i),z=vertices.getZ(i);vertices.setY(i,surfaceHeight(world,x,z));const c=new THREE.Color(world==='Moon'?0xa2a4a6:0xb36a43);c.multiplyScalar(.72+random()*.35);colors.push(c.r,c.g,c.b);}terrain.setAttribute('color',new THREE.Float32BufferAttribute(colors,3));terrain.computeVertexNormals();const ground=new THREE.Mesh(terrain,new THREE.MeshStandardMaterial({vertexColors:true,roughness:1}));ground.receiveShadow=true;scene.add(ground);
 const rocks=new THREE.InstancedMesh(new THREE.DodecahedronGeometry(1,0),new THREE.MeshStandardMaterial({color:world==='Moon'?0x777b81:0x87503a,roughness:1}),210);const dummy=new THREE.Object3D();for(let i=0;i<210;i++){let x,z;do{x=(random()-.5)*225;z=(random()-.5)*225;}while(sites.some(s=>Math.hypot(x-s.x,z-s.z)<7));const size=.12+random()*.52;dummy.position.set(x,surfaceHeight(world,x,z)+size*.3,z);dummy.scale.set(size*(.7+random()),size*.65,size);dummy.rotation.set(random(),random()*6,random());dummy.updateMatrix();rocks.setMatrixAt(i,dummy.matrix);}rocks.castShadow=true;scene.add(rocks);
 if(world==='Moon'){const positions=[];for(let i=0;i<800;i++){const a=random()*Math.PI*2,h=.08+random()*.92,r=230;positions.push(Math.cos(a)*Math.sqrt(1-h*h)*r,h*r,Math.sin(a)*Math.sqrt(1-h*h)*r);}const stars=new THREE.BufferGeometry();stars.setAttribute('position',new THREE.Float32BufferAttribute(positions,3));scene.add(new THREE.Points(stars,new THREE.PointsMaterial({color:0xcadfff,size:.35,fog:false})));const earth=new THREE.Mesh(new THREE.SphereGeometry(3,24,18),new THREE.MeshStandardMaterial({color:0x3682cb,emissive:0x0b204a,roughness:1}));earth.position.set(-70,60,-160);scene.add(earth);}
 const anchors=sites.map(site=>{const group=new THREE.Group();group.position.set(site.x,site.y,site.z);scene.add(group);const light=new THREE.Mesh(new THREE.RingGeometry(.8,1,48),new THREE.MeshBasicMaterial({color:world==='Moon'?0x6cceff:0xffc866,side:THREE.DoubleSide,transparent:true,opacity:.65}));light.rotation.x=-Math.PI/2;light.position.y=.035;group.add(light);const label=document.createElement('button');label.className='surface-marker';label.dataset.surfaceSite=site.artifact.id;label.setAttribute('aria-label',`Go near ${site.artifact.name}`);label.textContent=site.artifact.name+(site.artifact.locationUncertain?' · unconfirmed':'');$('.surface-expedition').append(label);return {...site,group,light,label,loaded:false,loading:false,radius:Math.max(.55,modelSpan(site.artifact)*.31)};});
 const loader=new GLTFLoader(),draco=new DRACOLoader();draco.setDecoderPath('vendor/draco/');loader.setDRACOLoader(draco);
 function fit(model,site){model.updateMatrixWorld(true);const box=new THREE.Box3().setFromObject(model),size=box.getSize(new THREE.Vector3()),center=box.getCenter(new THREE.Vector3()),holder=new THREE.Group();model.position.set(-center.x,-box.min.y,-center.z);holder.scale.setScalar(modelSpan(site.artifact)/Math.max(size.x,size.z,.01));holder.add(model);model.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});site.group.add(holder);resources.add(holder);site.loaded=true;}
 async function load(site){if(site.loading||site.loaded)return;site.loading=true;try{const a=site.artifact;if(a.id==='eagle'){fit(createDescentMarker(),site);return;}if(a.modelType){fit(createHeritageModel(a.modelType,{simple:true}),site);return;}let pending=cache.get(a.model);if(!pending){pending=loader.loadAsync(`assets/${a.model}`);cache.set(a.model,pending);}const gltf=await pending;if(dead)return;const model=gltf.scene.clone(true);enhanceModel(model,a.id,renderer);fit(model,site);}catch{if(!dead){site.label.classList.add('surface-model-failed');site.label.title='3D could not load. The complete story is still available.';site.loaded=true;}}finally{site.loading=false;}}
 anchors.forEach(s=>{if(s.artifact.modelType||s.artifact.id==='eagle')load(s);});
 const obstacles=anchors.map(s=>({x:s.x,z:s.z,radius:s.radius}));
 function resize(){const width=stage.clientWidth,height=stage.clientHeight;renderer.setSize(width,height,false);camera.aspect=width/Math.max(1,height);camera.updateProjectionMatrix();}const observer=new ResizeObserver(resize);observer.observe(stage);resize();
 function clearInput(){keys.clear();touch.clear();drag=null;root.querySelectorAll('[data-surface-move]').forEach(b=>b.classList.remove('held'));}
 function focus(){canvas.focus({preventScroll:true});}
 function jumpTo(id){const site=anchors.find(s=>s.artifact.id===id);if(!site)return;clearInput();const distance=Math.max(5,site.radius+3);const eye=surfaceHeight(world,site.x,site.z+distance)+1.65;const aim=site.y+Math.min(modelSpan(site.artifact)*.35,1.5);pitch=Math.atan2(aim-eye,distance);yaw=0;state={x:site.x,z:site.z+distance,yaw,pitch};nearest=site;uiTime=-Infinity;$('#surface-destination').value=id;$('.surface-status').textContent=`Near ${site.artifact.name}. Press E or Explore to open its story.`;load(site);focus();}
 function explore(){if(nearest&&Math.hypot(state.x-nearest.x,state.z-nearest.z)<Math.max(8,nearest.radius+3)){clearInput();if(document.pointerLockElement===canvas)document.exitPointerLock();onArtifact(nearest.artifact.id);}}
 const keyDown=e=>{if(paused||!$('.surface-help').hidden||document.querySelector('.echo-chat-panel,.modal,.reading-story,.voyage')||e.target.closest('input,select,textarea'))return;if(['KeyW','KeyA','KeyS','KeyD','ArrowLeft','ArrowRight','ArrowUp','ArrowDown','ShiftLeft','ShiftRight'].includes(e.code)){e.preventDefault();keys.add(e.code);}if(e.code==='KeyE'&&!e.repeat){e.preventDefault();explore();}};
 const keyUp=e=>keys.delete(e.code);
 const pointerDown=e=>{if(paused)return;focus();drag={id:e.pointerId,x:e.clientX,y:e.clientY};moved=false;canvas.setPointerCapture(e.pointerId);};
 const pointerMove=e=>{if(paused)return;let dx=0,dy=0;if(document.pointerLockElement===canvas){dx=e.movementX;dy=e.movementY;}else if(drag&&drag.id===e.pointerId){dx=e.clientX-drag.x;dy=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;}else return;if(Math.abs(dx)+Math.abs(dy)>1)moved=true;yaw-=dx*.003;pitch=Math.max(-1.15,Math.min(1.15,pitch-dy*.0025));};
 const pointerUp=()=>{drag=null;};
 const click=e=>{const direction=e.target.closest('[data-surface-move]')?.dataset.surfaceMove;if(direction&&!paused){const input={forward:direction==='forward'?1:direction==='back'?-1:0,right:direction==='right'?1:direction==='left'?-1:0};for(let i=0;i<2;i++)state=advanceWalker({...state,yaw,pitch},input,.1,{world,obstacles});}const action=e.target.closest('[data-surface-action]')?.dataset.surfaceAction;if(action==='exit')onExit();if(action==='explore')explore();if(action==='help'){const help=$('.surface-help');help.hidden=!help.hidden;$('[aria-label="Walking controls"]').setAttribute('aria-expanded',String(!help.hidden));clearInput();if(help.hidden)focus();}if(action==='mouse'){canvas.requestPointerLock?.()?.catch?.(()=>{$('.surface-status').textContent='Mouse lock unavailable. Drag the view or use arrow keys to look around.';});focus();}const id=e.target.closest('[data-surface-site]')?.dataset.surfaceSite;if(id)jumpTo(id);};
 const change=e=>{if(e.target.id==='surface-destination')jumpTo(e.target.value);};
 const down=e=>{const button=e.target.closest('[data-surface-move]');if(!button||paused)return;e.preventDefault();button.setPointerCapture(e.pointerId);touch.add(button.dataset.surfaceMove);button.classList.add('held');};
 const up=e=>{const button=e.target.closest('[data-surface-move]');if(button){touch.delete(button.dataset.surfaceMove);button.classList.remove('held');}};
 root.addEventListener('click',click);root.addEventListener('change',change);root.addEventListener('pointerdown',down);root.addEventListener('pointerup',up);root.addEventListener('pointercancel',up);canvas.addEventListener('pointerdown',pointerDown);canvas.addEventListener('pointermove',pointerMove);canvas.addEventListener('pointerup',pointerUp);canvas.addEventListener('pointercancel',pointerUp);document.addEventListener('keydown',keyDown);document.addEventListener('keyup',keyUp);window.addEventListener('blur',clearInput);
 const chatOpen=()=>pause(true),chatClose=()=>{if(!root.inert)pause(false);};document.addEventListener('echo-chat-open',chatOpen);document.addEventListener('echo-chat-close',chatClose);
 function pause(value){paused=!!value;clearInput();lastTime=0;if(paused&&document.pointerLockElement===canvas)document.exitPointerLock();}
 const point=new THREE.Vector3();let uiTime=0;
 function tick(time){if(dead)return;frame=requestAnimationFrame(tick);const dt=lastTime?Math.min(.1,(time-lastTime)/1000):0;lastTime=time;if(paused)return;elapsed+=dt;
  const input={forward:Number(keys.has('KeyW')||touch.has('forward'))-Number(keys.has('KeyS')||touch.has('back')),right:Number(keys.has('KeyD')||touch.has('right'))-Number(keys.has('KeyA')||touch.has('left')),lookX:Number(keys.has('ArrowLeft'))-Number(keys.has('ArrowRight')),lookY:Number(keys.has('ArrowUp'))-Number(keys.has('ArrowDown')),sprint:keys.has('ShiftLeft')||keys.has('ShiftRight')};
  state=advanceWalker({...state,yaw,pitch},input,dt,{world,obstacles});yaw=state.yaw;pitch=state.pitch;camera.position.set(state.x,state.y+(!reduced&&(input.forward||input.right)?Math.sin(elapsed*7)*.018:0),state.z);camera.rotation.set(pitch,yaw,0);
  nearest=anchors.reduce((best,s)=>!best||Math.hypot(state.x-s.x,state.z-s.z)<Math.hypot(state.x-best.x,state.z-best.z)?s:best,null);
  if(time-uiTime>180){uiTime=time;const distance=nearest?Math.hypot(state.x-nearest.x,state.z-nearest.z):Infinity,near=distance<Math.max(8,nearest.radius+3);const button=$('[data-surface-action="explore"]');button.disabled=!near;button.textContent=near?`Explore ${nearest.artifact.name}`:'Walk toward an artifact';$('.surface-distance').textContent=nearest?`${nearest.artifact.name} · ${Math.round(distance)} m in this scene`:'';
   for(const site of anchors){const distance=Math.hypot(state.x-site.x,state.z-site.z);if(distance<35)load(site);point.set(site.x,site.y+Math.min(modelSpan(site.artifact),3)+1,site.z).project(camera);site.label.hidden=point.z<0||point.z>1||Math.abs(point.x)>1||Math.abs(point.y)>1||distance>60||distance<3;if(!site.label.hidden){site.label.style.left=`${(point.x*.5+.5)*stage.clientWidth}px`;site.label.style.top=`${(-point.y*.5+.5)*stage.clientHeight}px`;}}
  }
  renderer.render(scene,camera);
 }frame=requestAnimationFrame(tick);focus();
 return {pause,focus,jumpTo,dispose(){if(dead)return;dead=true;cancelAnimationFrame(frame);clearInput();if(document.pointerLockElement===canvas)document.exitPointerLock();observer.disconnect();root.removeEventListener('click',click);root.removeEventListener('change',change);root.removeEventListener('pointerdown',down);root.removeEventListener('pointerup',up);root.removeEventListener('pointercancel',up);canvas.removeEventListener('pointerdown',pointerDown);canvas.removeEventListener('pointermove',pointerMove);canvas.removeEventListener('pointerup',pointerUp);canvas.removeEventListener('pointercancel',pointerUp);document.removeEventListener('keydown',keyDown);document.removeEventListener('keyup',keyUp);window.removeEventListener('blur',clearInput);document.removeEventListener('echo-chat-open',chatOpen);document.removeEventListener('echo-chat-close',chatClose);const seen=new Set();scene.traverse(o=>{if(o.geometry&&!seen.has(o.geometry)){seen.add(o.geometry);o.geometry.dispose();}for(const material of(o.material?(Array.isArray(o.material)?o.material:[o.material]):[])){if(seen.has(material))continue;seen.add(material);for(const item of Object.values(material))if(item?.isTexture&&!seen.has(item)){seen.add(item);item.dispose();}material.dispose();}});for(const promise of cache.values())promise.then(gltf=>{gltf.scene.traverse(o=>{if(o.geometry&&!seen.has(o.geometry)){seen.add(o.geometry);o.geometry.dispose();}});}).catch(()=>{});draco.dispose();renderer.dispose();renderer.forceContextLoss();root.replaceChildren();}};
}
